"""bottleopener_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +y from 1 extrusion(s) and 3 cut(s), applied in order;
each is an outline in the xz plane between two levels. Units: mm.
Run:  python bottleopener_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = -5.5    # level along y
z1 = -4.5    # level along y
z2 = 4.5    # level along y
z3 = 5.5    # level along y
hole_d = 9.5

DIR = (0, 1, 0)


def P(a, b):
    """Point (x, z) in the sketch plane (y = 0)."""
    return (a, 0, b)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: y -5.5 to 5.5 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(88.0, -9.0), P(0.0, -9.0)),
    Edge.makeThreePointArc(P(0.0, -9.0), P(-9.0, 0.0), P(0.0, 9.0)),
    cf.segment(P(0.0, 9.0), P(49.0, 9.0)),
    Edge.makeThreePointArc(P(49.0, 9.0), P(51.2551, 7.5791), P(50.9489, 4.9342)),
    Edge.makeThreePointArc(P(50.9489, 4.9342), P(50.5898, -0.8174), P(55.889, -3.0908)),
    cf.segment(P(55.889, -3.0908), P(78.389, 1.6892)),
    Edge.makeThreePointArc(P(78.389, 1.6892), P(80.7857, 2.9473), P(82.1803, 5.2886)),
    Edge.makeThreePointArc(P(82.1803, 5.2886), P(87.6496, 8.9576), P(92.0, 4.0)),
    cf.segment(P(92.0, 4.0), P(92.0, -5.0)),
    Edge.makeThreePointArc(P(92.0, -5.0), P(90.8284, -7.8284), P(88.0, -9.0)),
)
part = prism(outline_1, z0, z3)

# ---- 2. cut: y -5.5 to -4.5 ------------------------------
outline_2 = cf.wire(
    cf.segment(P(88.0, -8.0), P(0.0, -8.0)),
    Edge.makeThreePointArc(P(0.0, -8.0), P(-8.0, 0.0), P(0.0, 8.0002)),
    cf.segment(P(0.0, 8.0002), P(49.5087, 7.9368)),
    Edge.makeThreePointArc(P(49.5087, 7.9368), P(50.4443, 6.9049), P(50.1668, 5.5573)),
    Edge.makeThreePointArc(P(50.1668, 5.5573), P(49.7282, -1.3468), P(56.0878, -4.0751)),
    cf.segment(P(56.0878, -4.0751), P(79.4943, 0.9536)),
    Edge.makeThreePointArc(P(79.4943, 0.9536), P(82.0955, 2.9313), P(83.3463, 5.671)),
    Edge.makeThreePointArc(P(83.3463, 5.671), P(87.8535, 7.9079), P(91.0006, 4.0)),
    cf.segment(P(91.0006, 4.0), P(90.9763, -5.3765)),
    Edge.makeThreePointArc(P(90.9763, -5.3765), P(89.9284, -7.2981), P(88.0, -8.0)),
)
part = part - prism(outline_2, z0, z1)

# ---- round holes: (x, z, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (0.0, 0.0, hole_d, z1, z2),
]:
    part = part - hole(a, b, d, lo, hi)

# ---- 3. cut: y 4.5 to 5.5 ------------------------------
outline_3 = cf.wire(
    cf.segment(P(88.0, -8.0), P(0.0, -8.0)),
    Edge.makeThreePointArc(P(0.0, -8.0), P(-8.0, 0.0), P(0.0, 8.0002)),
    cf.segment(P(0.0, 8.0002), P(49.5087, 7.9368)),
    Edge.makeThreePointArc(P(49.5087, 7.9368), P(50.4443, 6.9049), P(50.1668, 5.5573)),
    Edge.makeThreePointArc(P(50.1668, 5.5573), P(49.7282, -1.3468), P(56.0878, -4.0751)),
    cf.segment(P(56.0878, -4.0751), P(79.4943, 0.9536)),
    Edge.makeThreePointArc(P(79.4943, 0.9536), P(82.0955, 2.9313), P(83.3463, 5.671)),
    Edge.makeThreePointArc(P(83.3463, 5.671), P(87.8535, 7.9079), P(91.0006, 4.0)),
    cf.segment(P(91.0006, 4.0), P(90.9763, -5.3765)),
    Edge.makeThreePointArc(P(90.9763, -5.3765), P(89.9284, -7.2981), P(88.0, -8.0)),
)
part = part - prism(outline_3, z2, z3)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "bottleopener_exact.step")
